/* ---------- capabilities ---------- */
async function boot() {
  try { if (window.claude) { db = await claude.use('db'); user = await claude.use('user'); } } catch (e) { db = null; }
  try { isOwner = user ? !!(await user.isOwner()) : false; } catch (e) { }
  try { me = user ? await user.id() : null; } catch (e) { }
  if (db) {
    try { db.collection('approved').onSnapshot(s => { approved = s.docs.map(d => ({ id: d.id, ...d.data() })); render(); }, () => { }); } catch (e) { }
    try { db.collection('appeals').onSnapshot(s => { appealsDb = s.docs.map(d => ({ id: d.id, ...d.data() })); if (/appeal/.test(route().v)) render(); }, () => { }); } catch (e) { }
    if (isOwner) try { db.collection('subs').onSnapshot(s => { subs = s.docs.flatMap(d => (d.data().items || []).map((it, i) => ({ id: d.id + '_' + i, ...it }))).sort((a, b) => b.at - a.at); render(); }, () => { }); } catch (e) { }
    if (me) try { const p = await db.collection('data/users/' + me).doc('profile').get(); if (p && p.exists) { profile = p.data(); store.set('profile', profile); render(); } } catch (e) { }
  }
  render();
}
async function submit(kind, data, msg, ok) {
  const rec = { kind, data, at: Date.now(), org: profile?.org || null };
  let saved = false;
  if (db && me) { try { const ref = db.collection('subs').doc(me); const cur = await ref.get(); const items = (cur && cur.exists && cur.data().items) || []; items.push(rec); await ref.set({ items: items.slice(-200), at: Date.now() }); saved = true; } catch (e) { saved = false; } }
  const q = store.get('mine', []); q.unshift(rec); store.set('mine', q.slice(0, 50));
  showSent(saved, msg, ok);
}
function showSent(saved, msg, ok) {
  modal(`<div class="mhead"><h3>${saved ? (ok?.title || 'Sent to the hub team') : 'Almost there'}</h3><button class="ib" data-close>${ic('x')}</button></div>
  <p>${saved ? (ok?.text || 'It’s in the approval queue. You’ll see it on the hub once it’s checked.') : 'This preview couldn’t save it automatically. Copy the message below and send it on WhatsApp or by email.'}</p>
  ${msg && !saved ? `<div class="msg" id="mtxt">${esc(msg)}</div><div class="row" style="margin-top:10px"><button class="btn p sm" data-copy="#mtxt">${ic('copy')} Copy message</button><a class="btn s sm" href="https://wa.me/${WA}?text=${encodeURIComponent(msg)}" target="_blank" rel="noopener">${ic('wa')} Open WhatsApp</a></div><p class="note" style="margin-top:8px">WhatsApp 07931 814538 · ${EMAIL}</p>` : ''}`);
}
const saveProfile = async p => { profile = p; store.set('profile', p); if (db && me) { try { await db.collection('data/users/' + me).doc('profile').set(p); } catch (e) { } } };

