function logoStrip() {
  const L = H.DIR.filter(o => o.lg).slice(0, 40);
  return `<div class="scroll" style="gap:28px;align-items:center;mask-image:linear-gradient(90deg,transparent,#000 6%,#000 94%,transparent)">${L.map(o => `<a href="#org-${o.id}" style="flex:none" title="${esc(o.n)}"><img src="lg/${o.lg}.webp" alt="${esc(o.n)}" style="height:52px;width:auto;max-width:150px;object-fit:contain" loading="lazy"></a>`).join('')}</div>`;
}
function newFeed() {
  const out = [];
  approved.filter(a => a.status === 'live' && isNewTs(a.at) && ['listing','help','vol','event','activity','youth','staff','funding','offer','need'].includes(a.kind) && !(a.kind === 'need' && (a.met || (a.data?.deadline && a.data.deadline < ISO(TODAY))))).forEach(a => out.push({ t: a.data?.title || a.data?.name || 'New listing', d: a.data?.details || '', k: kindLabel(a.kind), h: kindRoute(a.kind), ts: a.at }));
  const soon = H.EV.filter(e => e.s >= ISO(TODAY) && e.s <= ISO(new Date(+TODAY + 10 * 864e5))).slice(0, 3);
  soon.forEach(e => out.push({ t: e.t, d: e.when + ' · ' + (e.where || ''), k: 'Event', h: 'events' }));
  H.WO.filter(w => w.isNew).slice(0, 2).forEach(w => out.push({ t: w.t, d: w.d, k: 'Activity', h: 'activities' }));
  out.push({ t: (window.DEALS || []).length + ' discounts for students, NHS, teachers and more', d: 'New: student deals, NHS and school staff offers, forces and carers discounts, all checked 24 Nov 2026.', k: 'Discounts', h: 'discounts' });
  (window.DEALS || []).filter(x => x.ex).slice(0, 2).forEach(x => out.push({ t: x.b + ': ' + x.o, d: 'Ends ' + new Date(x.ex).toLocaleDateString('en-GB', { day: 'numeric', month: 'short' }), k: 'Discount', h: 'discounts' }));
  out.push({ t: 'Staff discounts for your team', d: 'Check what school, NHS, charity and mosque staff can claim.', k: 'Discounts', h: 'staff' });
  (window.FUNDS || []).filter(f => f.dl && f.st !== 'closed').map(f => [f, Math.ceil((new Date(f.dl + 'T23:59:59') - TODAY) / 864e5)]).filter(([, d]) => d >= 0 && d <= 25).sort((a, z) => a[1] - z[1]).forEach(([f, d]) => out.unshift({ t: 'Closing soon: ' + f.n, d: (f.at ? f.at.split(/[;(]/)[0].trim() + ' · ' : '') + 'deadline ' + new Date(f.dl).toLocaleDateString('en-GB', { day: 'numeric', month: 'short' }) + ' (' + d + ' day' + (d === 1 ? '' : 's') + ')', k: 'Funding', h: 'funding' }));
  return out;
}
const kindLabel = k => ({ listing: 'Directory', help: 'Community Support Services', vol: 'Volunteering Opportunities', event: 'Event', activity: 'Activity', youth: 'Youth discount', staff: 'Staff discount', funding: 'Funding', offer: 'Local offer', need: 'Urgent need', 'free-post': 'Free post' }[k] || 'Update');
const kindRoute = k => ({ listing: 'directory', help: 'help', vol: 'volunteering', event: 'events', activity: 'activities', youth: 'youth', staff: 'staff', funding: 'funding', offer: 'discounts', need: 'needs' }[k] || 'home');

