V.help = () => {
  const extra = appr('help').map(a => ({ id: 'a' + a.id, n: a.data.title, org: a.data.org || '', cat: (a.data.cats || '').split(',').map(x => x.trim()).filter(Boolean), help: a.data.details, who: [a.data.who, a.data.elig].filter(Boolean).join('. '), how: [a.data.access, a.data.times, a.data.langs ? 'Languages: ' + a.data.langs : ''].filter(Boolean).join(' · '), locs: a.data.address ? [[a.data.address, '']] : [], web: a.data.link, added: a.at }));
  const all = [...extra, ...HELP];
  const list = all.filter(s => (hCat === 'all' || (s.cat || []).includes(hCat)) && (!hQ || JSON.stringify([s.n, s.org, s.help]).toLowerCase().includes(hQ)));
  return `<div class="wrap">${back('home', 'Home', 'Community Support Services')}<div class="sec-h"><div><h1>Community Support Services</h1><p class="lede">Support services across Luton: food, money, housing, mental health, families, refugees and more. Find what’s available for the people you work with, and share it with them.</p><div class="row dbtns" style="margin:12px 0"><button class="btn p" data-add="help" data-mode="own">${tic('add', 'ti xs')} List your service</button><button class="btn s" data-add="help" data-mode="recommend">Recommend a service</button></div><p class="note">${all.length} services. Checked ${esc(window.NGSHELP?.checked || '')}. In an emergency call 999. Samaritans: 116 123 any time.</p></div></div>
  <input class="in" id="hQ" placeholder="What do they need? e.g. food, rent, baby" value="${esc(hQ)}" aria-label="Search help">
  <div class="scroll" style="margin:12px 0">${[['all', 'All'], ...Object.entries(HCAT)].map(([c, t]) => `<button class="chip${hCat === c ? ' on' : ''}" data-hcat="${c}">${t}</button>`).join('')}</div>
  
  <div class="grid">${list.map(s => `<article class="card"><div class="row" style="justify-content:space-between">${logoImg(s.lg, s.org || s.n, s.tc)}${s.added && isNewTs(s.added) ? '<span class="tag new">New</span>' : ''}</div><h3>${esc(s.n)}</h3><div class="meta">${esc(s.org)}</div><p>${esc(s.help)}</p>
  ${s.who ? `<p class="note"><b>Who:</b> ${esc(s.who)}</p>` : ''}${s.how ? `<p class="note"><b>How:</b> ${esc(s.how)}</p>` : ''}
  <div class="meta">${(s.d || []).length ? `<span class="tag">${s.d.map(d => DAYS[d]).join(', ')}</span>` : ''}${s.h ? `<span>${esc(s.h)}</span>` : ''}${s.locs?.[0] ? `<span>${esc(s.locs[0][0])} ${esc(s.locs[0][1])}</span>` : ''}</div>
  <div class="row">${okUrl(s.web) ? `<a class="btn s sm" href="${esc(okUrl(s.web))}" target="_blank" rel="noopener">Details</a>` : ''}${saveBtn('service', s.id || slug(s.n), s.n, 'help')}<button class="btn p sm" data-sharem="${esc(s.n + (s.org && s.org !== s.n ? ' (' + s.org + ')' : '') + '\n' + (s.help || '') + (s.who ? '\nWho: ' + s.who : '') + (s.how ? '\nHow: ' + s.how : '') + ((s.d || []).length ? '\nWhen: ' + s.d.map(d => DAYS[d]).join(', ') + (s.h ? ' ' + s.h : '') : '') + (s.locs?.[0] ? '\nWhere: ' + s.locs[0][0] + ' ' + s.locs[0][1] : '') + (s.web ? '\n' + s.web : '') + '\n\nFound on Luton Community Hub')}">${ic('wa')} Share</button></div></article>`).join('') || '<div class="empty">No matches.</div>'}</div>${POWERED}${keepExploring('help')}</div>`;
};

