/* youth & staff discounts */
V.youth = () => `<div class="wrap">${back('home', 'Home', 'Youth discounts')}<h1>Discounts for young people</h1><p class="note">Share these with students and families. Always check the provider’s current terms.</p>${addBar('youth', 'a discount')}
  <div class="grid">${[...appr('youth').map(a => ({ t: a.data.title, save: '', ages: '', d: a.data.details, url: a.data.link })), ...H.DL].map(d => `<article class="card"><span class="tag">${esc(d.save || 'Discount')}</span><h3>${esc(d.t)}</h3><div class="meta">${esc(d.ages || '')}</div><p>${esc(d.d)}</p><div class="row">${okUrl(d.url) ? `<a class="btn s sm" href="${esc(okUrl(d.url))}" target="_blank" rel="noopener">Get it</a>` : ''}<button class="btn p sm" data-share="${esc(d.t + ': ' + d.d + ' ' + (d.url || ''))}">${ic('wa')} Share</button></div></article>`).join('')}</div>${POWERED}</div>`;
