/* ===== Discounts (students, NHS, teachers, charity, forces, carers) ===== */
const DEALS = (window.DEALS || []);
const DTABS = [['all', 'All'], ['stu', 'Students & young people'], ['nhs', 'NHS & health'], ['tea', 'Teachers & schools'], ['cha', 'Charity & volunteers'], ['emg', 'Emergency services & forces'], ['car', 'Carers & disabled people']];
const DTYPES = ['% off', '£ off', 'Free item', 'Free trial', 'BOGOF', 'Free delivery', 'Cheaper price', 'Cheaper tickets', 'Free entry', 'Membership'];
let dF = { q: '', ty: '', wh: '', acc: '', cat: '', aud: '', local: false, rv: { tab: '', src: '', st: '', q: '' } };
const DISCLOSE = 'Deals are listed for information. We’re not partnered with these sites. Some links may earn us a small commission in future.';
const hiddenDeals = () => { const m = approved.find(a => a.id === 'deals-hidden'); const ids = (m && m.ids) || store.get('hiddenDeals', []); return new Set(ids); };
async function saveHidden(set) { const ids = [...set]; store.set('hiddenDeals', ids); if (db && isOwner) { try { await db.collection('approved').doc('deals-hidden').set({ kind: 'deals-hidden', status: 'meta', ids, at: Date.now() }); } catch (e) { toast('Saved on this device only'); } } }
const dDays = ex => ex ? Math.ceil((new Date(ex + 'T23:59:59') - TODAY) / 864e5) : null;
const localOffers = () => appr('offer').map(a => { const d = a.data || {}; return { id: 'local-' + a.id, b: d.title || d.business || 'Local offer', o: d.offer || d.details || '', ty: d.type || '% off', cat: 'Local', tabs: ['all', ...(d.tab ? [d.tab] : [])], aud: [d.who || 'Everyone'], req: d.req || 'See details', wh: d.where || 'In-store', acc: ['None – show ID'], how: d.details || 'Ask in store or follow the link.', link: okUrl(d.link) || '', src: ['Local · Luton'], ex: d.expiry || null, vg: false, nt: d.address ? 'Address: ' + d.address : null, tint: '#FFD23F', ck: new Date(a.at).toISOString().slice(0, 10), local: 1, addr: d.address || '', contact: d.contact || '' }; });
const allDeals = (incHidden = false) => { const h = hiddenDeals(); return [...localOffers(), ...DEALS.filter(x => incHidden || !h.has(x.id))].filter(x => { const dd = dDays(x.ex); return dd === null || dd >= 0; }); };
const dealBtns = (where = '') => `<div class="row dbtns"><button class="btn p sm" data-add="offer" data-mode="own">${tic('add', 'ti xs')} List your offer</button><button class="btn s sm" data-add="offer" data-mode="recommend">Recommend a local offer</button>${where}</div>`;
function dealCard(x) {
  const dd = dDays(x.ex), soon = dd !== null && dd <= 14;
  const chips = [x.local ? '<span class="tag new">Local · Luton</span>' : '', `<span class="tag">${esc(x.ty)}</span>`, `<span class="tag">${esc(x.wh)}</span>`, ...x.aud.slice(0, 3).map(a => `<span class="tag ok">${esc(a)}</span>`)].join('');
  return `<article class="card deal" style="--tint:${esc(x.tint || '#3A3FD9')}"><div class="dbar"></div><div class="row" style="justify-content:space-between;gap:8px"><h3>${esc(x.b)}</h3>${soon ? `<span class="stamp wait">${dd <= 0 ? 'Ends today' : 'Ends in ' + dd + ' day' + (dd === 1 ? '' : 's')}</span>` : x.ex ? `<span class="stamp">Until ${esc(new Date(x.ex).toLocaleDateString('en-GB', { day: 'numeric', month: 'short' }))}</span>` : ''}</div>
  <p class="doff">${esc(x.o)}</p>${x.vg ? `<p class="note"><b>Exact discount shown after signing in to ${esc(x.acc[0])}.</b></p>` : ''}
  <div class="chips sm">${chips}</div>
  <dl class="dl sm2"><dt>Requirement</dt><dd>${esc(x.req)}</dd><dt>Account</dt><dd>${esc(x.acc.join(' or '))}</dd><dt>How to claim</dt><dd>${esc(x.how)}</dd>${x.nt ? `<dt>Note</dt><dd>${esc(x.nt)}</dd>` : ''}</dl>
  <div class="row">${okUrl(x.link) ? `<a class="btn s sm" href="${esc(okUrl(x.link))}" target="_blank" rel="noopener">Find out more</a>` : ''}${saveBtn('deal', x.id, x.b + ': ' + x.o, 'discounts')}<button class="btn p sm" data-share="${esc(x.b + ': ' + x.o + (x.link ? ' ' + x.link : ''))}">${ic('wa')} Share</button></div>
  <p class="cred">${x.local ? 'Listed by a Luton business · checked by the hub' : 'Available via ' + esc(x.src.filter(s => s !== 'Brand website').join(', ') || 'the brand')}${x.src.includes('Brand website') && x.src.length > 1 ? ' and the brand' : ''} · checked ${esc(new Date(x.ck).toLocaleDateString('en-GB', { day: 'numeric', month: 'short', year: 'numeric' }))}</p></article>`;
}
V.discounts = (tab = 'all') => {
  if (!DTABS.find(t => t[0] === tab)) tab = 'all';
  const base = allDeals().filter(x => tab === 'all' || x.tabs.includes(tab) || x.local);
  const q = dF.q.toLowerCase();
  const list = base.filter(x => (!q || (x.b + ' ' + x.o + ' ' + x.cat + ' ' + x.aud.join(' ')).toLowerCase().includes(q)) && (!dF.ty || x.ty === dF.ty) && (!dF.wh || x.wh.toLowerCase().includes(dF.wh)) && (!dF.acc || x.acc.join(' ').includes(dF.acc)) && (!dF.cat || x.cat === dF.cat) && (!dF.aud || x.aud.join(' ').includes(dF.aud)) && (!dF.local || x.local)).sort((a, z) => (z.local || 0) - (a.local || 0));
  const uniq = f => [...new Set(base.flatMap(f))].filter(Boolean).sort();
  const sel = (k, label, opts) => `<label class="f sm">${label}<select class="in" data-df="${k}"><option value="">Any</option>${opts.map(o => `<option ${dF[k] === o ? 'selected' : ''}>${esc(o)}</option>`).join('')}</select></label>`;
  const accs = uniq(x => x.acc.flatMap(a => a.split(' / ')));
  return `<div class="wrap">${back('home', 'Home', 'Discounts')}<h1>Discounts</h1><p class="lede">Deals for students and young people, and for people who work or volunteer in the NHS, schools, charities, the emergency services and care. Local Luton offers come first.</p>
  ${dealBtns()}
  <div class="scroll dtabs" role="tablist">${DTABS.map(([k, t]) => `<a role="tab" aria-selected="${k === tab}" class="chip ${k === tab ? 'on' : ''}" href="#discounts${k === 'all' ? '' : '-' + k}">${esc(t)} <small>${allDeals().filter(x => k === 'all' || x.tabs.includes(k)).length}</small></a>`).join('')}</div>
  <div class="dfil"><label class="f sm grow">Search<input class="in" type="search" data-df="q" value="${esc(dF.q)}" placeholder="Brand, food, travel, gym…"></label>
  ${sel('ty', 'Discount type', uniq(x => [x.ty]))}${sel('cat', 'Category', uniq(x => [x.cat]))}${sel('aud', 'Who it’s for', uniq(x => x.aud))}${sel('wh', 'Where', ['online', 'in-store'])}${sel('acc', 'Account needed', accs)}
  <label class="chk"><input type="checkbox" data-df="local" ${dF.local ? 'checked' : ''}> Local · Luton only</label></div>
  <p class="note">${list.length} deal${list.length === 1 ? '' : 's'} · Checked on 24 Nov 2026 · offers change, so check the site for the latest. We never post discount codes.</p>
  ${list.length ? `<div class="grid">${list.map(dealCard).join('')}</div>` : `<div class="empty"><p>No deals match yet. Know a good one?</p>${dealBtns()}</div>`}
  <div class="addbar" style="margin-top:20px">${tic('add', 'ti')}<b>Run a Luton business or organisation with an offer for students, staff or volunteers?</b>${dealBtns()}</div>
  <p class="note disclose">${DISCLOSE}</p>${POWERED}</div>`;
};
V.dealreview = () => {
  if (!isOwner) return `<div class="wrap"><div class="empty">Reviewing deals is for the hub owner.</div></div>`;
  const h = hiddenDeals(), r = dF.rv, q = r.q.toLowerCase();
  const rows = DEALS.filter(x => (!r.tab || x.tabs.includes(r.tab)) && (!r.src || x.src.includes(r.src)) && (!r.st || (r.st === 'removed' ? h.has(x.id) : r.st === 'vague' ? x.vg : !h.has(x.id))) && (!q || (x.b + ' ' + x.o).toLowerCase().includes(q)));
  const srcs = [...new Set(DEALS.flatMap(x => x.src))].sort();
  return `<div class="wrap">${back('admin', 'Approval queue', 'Review deals')}<h1>Review deals</h1><p class="lede">${DEALS.length} gathered · ${h.size} removed · ${DEALS.filter(x => x.vg).length} need sign-in for exact details · ${DEALS.filter(x => x.ex).length} with an end date. Removed deals are hidden from the public Discounts page.</p>
  <div class="dfil"><label class="f sm grow">Search<input class="in" type="search" data-rv="q" value="${esc(r.q)}"></label>
  <label class="f sm">Tab<select class="in" data-rv="tab"><option value="">All</option>${DTABS.slice(1).map(([k, t]) => `<option value="${k}" ${r.tab === k ? 'selected' : ''}>${t}</option>`).join('')}</select></label>
  <label class="f sm">Source<select class="in" data-rv="src"><option value="">All</option>${srcs.map(s => `<option ${r.src === s ? 'selected' : ''}>${esc(s)}</option>`).join('')}</select></label>
  <label class="f sm">Status<select class="in" data-rv="st"><option value="">All</option><option value="kept" ${r.st === 'kept' ? 'selected' : ''}>Kept</option><option value="removed" ${r.st === 'removed' ? 'selected' : ''}>Removed</option><option value="vague" ${r.st === 'vague' ? 'selected' : ''}>Needs sign-in</option></select></label></div>
  <div class="row" style="margin:10px 0"><button class="btn s sm" data-rvall="1">Select all shown</button><button class="btn s sm" data-rvall="0">Clear selection</button><button class="btn o sm" data-rvbulk="remove">Remove selected</button><button class="btn p sm" data-rvbulk="keep">Keep selected</button><button class="btn s sm" id="dealsCsv">${ic('dl')} Download CSV</button></div>
  <div class="scroll"><table class="dtab"><thead><tr><th></th><th>Status</th><th>Brand</th><th>Offer</th><th>Tabs</th><th>Type</th><th>Where</th><th>Account</th><th>Sources</th><th>Brand page</th><th>Verified via</th><th>Ends</th><th>Sign-in?</th></tr></thead><tbody>
  ${rows.map(x => `<tr class="${h.has(x.id) ? 'off' : ''}"><td><input type="checkbox" class="rvsel" value="${esc(x.id)}" aria-label="Select ${esc(x.b)}"></td><td><button class="btn sm ${h.has(x.id) ? 's' : 'p'}" data-rvt="${esc(x.id)}">${h.has(x.id) ? 'Removed' : 'Kept'}</button></td><td><b>${esc(x.b)}</b></td><td>${esc(x.o)}</td><td>${esc(x.tabs.map(t => (DTABS.find(z => z[0] === t) || [, t])[1]).join(', '))}</td><td>${esc(x.ty)}</td><td>${esc(x.wh)}</td><td>${esc(x.acc.join(', '))}</td><td>${x.dirs.map(u => `<a href="${esc(okUrl(u))}" target="_blank" rel="noopener">${esc(u.replace(/^https?:\/\/(www\.)?/, '').split('/')[0])}</a>`).join('<br>') || esc(x.src.join(', '))}</td><td>${x.bu ? `<a href="${esc(okUrl(x.bu))}" target="_blank" rel="noopener">Open</a>` : '—'}</td><td>${esc(x.lv)}</td><td>${esc(x.ex || '')}</td><td>${x.vg ? 'Yes' : ''}</td></tr>`).join('')}</tbody></table></div>
  <p class="note">Local offers from businesses arrive in the approval queue as “Local offer”.</p></div>`;
};
const dealsCsv = () => { const cols = ['id', 'b', 'o', 'ty', 'cat', 'tabs', 'aud', 'req', 'wh', 'acc', 'how', 'link', 'bu', 'dirs', 'lv', 'src', 'ex', 'vg', 'nt', 'ck']; const head = ['id', 'brand', 'offer', 'type', 'category', 'tabs', 'audience', 'requirement', 'where', 'account', 'how', 'link', 'brandUrl', 'directories', 'lastVerifiedVia', 'sources', 'expiry', 'vague', 'note', 'checked', 'status']; const h = hiddenDeals(); const c = v => '"' + (Array.isArray(v) ? v.join('; ') : v == null ? '' : String(v)).replace(/"/g, '""') + '"'; return [head.join(','), ...DEALS.map(x => [...cols.map(k => c(x[k])), c(h.has(x.id) ? 'removed' : 'kept')].join(','))].join('\n'); };
document.addEventListener('input', e => { const t = e.target; if (t.dataset.df === 'q') { dF.q = t.value; const p = t.selectionStart; render(); const n = $('[data-df="q"]'); if (n) { n.focus(); try { n.setSelectionRange(p, p); } catch (er) { } } } if (t.dataset.rv === 'q') { dF.rv.q = t.value; const p = t.selectionStart; render(); const n = $('[data-rv="q"]'); if (n) { n.focus(); try { n.setSelectionRange(p, p); } catch (er) { } } } });
document.addEventListener('change', e => { const t = e.target; if (t.dataset.df && t.dataset.df !== 'q') { dF[t.dataset.df] = t.type === 'checkbox' ? t.checked : t.value; render(); } if (t.dataset.rv && t.dataset.rv !== 'q') { dF.rv[t.dataset.rv] = t.value; render(); } });
document.addEventListener('click', async e => { const t = e.target.closest('button'); if (!t) return; const d = t.dataset;
  if (d.rvt) { const h = hiddenDeals(); h.has(d.rvt) ? h.delete(d.rvt) : h.add(d.rvt); await saveHidden(h); return render(); }
  if (d.rvall) { $$('.rvsel').forEach(c => c.checked = d.rvall === '1'); return; }
  if (d.rvbulk) { const ids = $$('.rvsel:checked').map(c => c.value); if (!ids.length) return toast('Select some rows first'); const h = hiddenDeals(); ids.forEach(i => d.rvbulk === 'remove' ? h.add(i) : h.delete(i)); await saveHidden(h); toast((d.rvbulk === 'remove' ? 'Removed ' : 'Kept ') + ids.length); return render(); }
  if (t.id === 'dealsCsv') return saveBlob(new Blob([dealsCsv()], { type: 'text/csv' }), 'all-deals.csv');
});

/* ===== Owner admin: queues by category ===== */
const QCATS = [['accounts', 'Account requests', ['account-request']], ['partners', 'Partner requests', ['partner-request']], ['listings', 'Listings (new, amend, remove)', ['listing', 'claim']], ['reports', 'Reports', ['report']], ['help', 'Help', ['help']], ['vol', 'Volunteering', ['vol']], ['events', 'Events', ['event']], ['acts', 'Activities', ['activity']], ['offers', 'Discounts & local offers', ['offer', 'youth', 'staff']], ['funding', 'Funding suggestions', ['funding', 'alert']], ['quest', 'Campaign questionnaires', ['campaign-questionnaire', 'campaign-brief']], ['reviews', 'Campaign reviews', ['campaign-review']], ['design', 'Design requests', ['design-request', 'change']], ['freeposts', 'Free posts', ['free-post']], ['needs', 'Urgent needs', ['need']], ['volapps', 'Volunteer applications', ['vol-application']], ['appeals', 'Appeals', ['appeal']], ['logoreq', 'Logo requests (48-hour target)', ['logo-update', 'logo-remove', 'logo-hide', 'logo-report']], ['verify', 'Verification claims', ['verify-claim', 'mosque-claim']], ['oms', 'OMS demos', ['oms-demo']], ['fundedp', 'Funded partnerships', ['funded-partnership']], ['lpd', 'Link page designs', ['link-page-design']], ['training', 'Training', ['training-session', 'training-rec']], ['probono', 'Skills board', ['probono-offer', 'probono-ask']], ['enq', 'Enquiries', ['enquiry']]];
const subStatus = s => (approved.find(a => a.id === s.id) || {}).status || 'new';
const pendingBy = () => { const open = subs.filter(s => subStatus(s) === 'new'); return Object.fromEntries(QCATS.map(([k, , kinds]) => [k, open.filter(s => kinds.includes(s.kind))])); };
const pendingTotal = () => Object.values(pendingBy()).reduce((t, l) => t + l.length, 0);
/* Self-contained summary. Data shape (for SMR Studio later):
   { total: number, pending: [{ key, label, count }], signupsThisWeek: number, fundsClosingSoon: [{ name, deadline }], newest: [{ kind, label, title, at }] } */
function hubSummaryData() { const p = pendingBy(); return { total: pendingTotal(), pending: QCATS.map(([k, l]) => ({ key: k, label: l, count: p[k].length })), signupsThisWeek: subs.filter(s => s.kind === 'signup' && isNewTs(s.at)).length, fundsClosingSoon: (window.FUNDS || []).filter(f => fSoon(f)).map(f => ({ name: f.n, deadline: f.dl })), newest: subs.filter(s => subStatus(s) === 'new' && s.kind !== 'signup').slice(0, 5).map(s => ({ kind: s.kind, label: ADMIN_LABEL[s.kind] || kindLabel(s.kind), title: s.data?.title || s.data?.org || s.data?.name || '', at: s.at })) }; }
window.LCH_SUMMARY = hubSummaryData;
function hubSummary() { const d = hubSummaryData(); return `<section class="hubsum"><div class="row" style="justify-content:space-between"><b>Community Hub</b><span class="stamp ${d.total ? 'wait' : 'ok'}">${d.total} waiting</span></div><div class="hsg"><div><small>New sign-ups this week</small><b>${d.signupsThisWeek}</b></div><div><small>Funds closing soon</small><b>${d.fundsClosingSoon.length}</b></div><div><small>Busiest queue</small><b>${esc((d.pending.slice().sort((a, z) => z.count - a.count)[0] || {}).count ? d.pending.slice().sort((a, z) => z.count - a.count)[0].label : 'All clear')}</b></div></div>${d.newest.length ? `<ul class="hsl">${d.newest.map(n => `<li><span class="tag">${esc(n.label)}</span> ${esc(n.title)} <small>${new Date(n.at).toLocaleDateString('en-GB')}</small></li>`).join('')}</ul>` : '<p class="note">Nothing new waiting.</p>'}</section>`; }
const qCard = s => { const st = subStatus(s); const show = d => Object.entries(d || {}).filter(([k, v]) => v && typeof v === 'string' && !['mode'].includes(k)).map(([k, v]) => `<dt>${esc(k)}</dt><dd>${esc(v)}</dd>`).join('');
  return `<div class="note-card q">${st === 'new' ? `<label class="chk" style="margin:0"><input type="checkbox" class="qsel" value="${esc(s.id)}"> Select</label>` : ''}<div class="row" style="justify-content:space-between"><span class="stamp">${esc(ADMIN_LABEL[s.kind] || kindLabel(s.kind))}${s.data?.mode ? ' · ' + esc(s.data.mode) : ''}</span><span class="stamp ${st === 'new' ? 'wait' : st === 'rejected' ? 'no' : 'ok'}">${st === 'new' ? 'Waiting' : st === 'rejected' ? 'Not approved' : 'Approved'}</span></div><b>${esc(s.data?.title || s.data?.org || s.data?.name || '')}</b><dl class="dl sm">${show(s.data)}</dl><span class="note">${new Date(s.at).toLocaleString('en-GB')}</span>${st === 'new' ? `<label class="f">Note (optional)<input class="in" data-note="${s.id}" placeholder="Shown with the decision"></label><div class="row"><button class="btn p sm" data-appr="${s.id}">Approve</button>${s.kind === 'account-request' ? '' : `<button class="btn s sm" data-edit="${s.id}">Edit & approve</button>`}<button class="btn o sm" data-rej="${s.id}">Reject</button></div>` : ''}</div>`; };
V.admin = (cat = '') => {
  if (!isOwner) return `<div class="wrap"><div class="empty">The approval queue is for the hub owner.</div></div>`;
  const p = pendingBy(), tot = pendingTotal();
  const tabs = `<div class="seg" style="margin:10px 0 16px"><a class="btn sm ${cat ? 's' : 'p'}" href="#admin">Waiting for approval</a><a class="btn sm s" href="#dealreview">Review deals</a><a class="btn sm s" href="#promos">Promotions</a><a class="btn sm s" href="#brandassets">Brand assets</a><a class="btn sm s" href="#needscall">Needs a call</a><a class="btn sm s" href="#analytics">Analytics</a><a class="btn sm s" href="#segments">Segments</a><a class="btn sm s" href="#jobs">Design jobs</a><a class="btn sm s" href="#magadmin">Luton This Week</a></div><p class="notice">Preview of the Community Hub section in SMR Studio. In the live set-up these pages live in SMR Studio (the admin app).</p>`;
  if (cat) { const q = QCATS.find(c => c[0] === cat); if (!q) return V.admin('');
    const list = subs.filter(s => q[2].includes(s.kind)).sort((a, z) => (subStatus(a) === 'new' ? 0 : 1) - (subStatus(z) === 'new' ? 0 : 1) || a.at - z.at);
    return `<div class="wrap">${back('admin', 'Waiting for approval', q[1])}<h1>${esc(q[1])}</h1>${tabs}<p class="lede">${p[cat].length} waiting · oldest first</p>
    ${p[cat].length ? `<div class="row" style="margin-bottom:12px"><button class="btn s sm" data-qall="1">Select all</button><button class="btn s sm" data-qall="0">Clear</button><button class="btn p sm" data-qbulk="appr">Approve selected</button><button class="btn o sm" data-qbulk="rej">Reject selected</button></div>` : ''}
    <div class="board notes wide">${list.map(qCard).join('') || '<div class="empty">Nothing here yet.</div>'}</div></div>`; }
  return `<div class="wrap">${back('home', 'Home', 'Admin')}<h1>Waiting for approval</h1>${tabs}
  <p class="note" style="margin:0 0 8px">Volunteers: <b>${subs.filter(s => s.kind === 'vol-signup').length}</b> signed up to be matched · <b>${subs.filter(s => s.kind === 'vol-application').length}</b> applications · Luton This Week: <b>${subs.filter(s => s.kind === 'weekly-signup').length}</b> sign-ups</p>
  <div class="qtot"><b>${tot}</b><span>${tot === 1 ? 'item is' : 'items are'} waiting for you</span></div>
  <div class="qgrid">${QCATS.map(([k, l]) => `<a class="qcat ${p[k].length ? '' : 'zero'}" href="#admin-${k}"><span>${esc(l)}</span><b class="badge">${p[k].length}</b></a>`).join('')}</div>
  <h2 style="margin-top:28px">Community Hub summary</h2>${hubSummary()}</div>`;
};
document.addEventListener('click', async e => { const t = e.target.closest('button'); if (!t) return; const d = t.dataset;
  if (d.qall) { $$('.qsel').forEach(c => c.checked = d.qall === '1'); return; }
  if (d.qbulk) { const ids = $$('.qsel:checked').map(c => c.value); if (!ids.length) return toast('Select some items first'); let n = 0;
    for (const id of ids) { const s = subs.find(x => x.id === id); if (!s) continue; const note = ($(`[data-note="${id}"]`)?.value || '').trim();
      try { if (d.qbulk === 'rej') await db.collection('approved').doc(id).set({ kind: s.kind, at: Date.now(), status: 'rejected', note }); else await approve(s, s.kind === 'account-request' ? { title: s.data.org, org: s.data.org } : s.data, note); n++; } catch (er) { } }
    toast((d.qbulk === 'rej' ? 'Rejected ' : 'Approved ') + n); return render(); }
});

