const saved = () => store.get('saved', []);
const isSaved = id => saved().some(x => x.id === id);
const saveBtn = (type, id, title, href) => { const on = isSaved(type + ':' + id); return `<button class="savebtn ${on ? 'on' : ''}" data-save="${esc(type + ':' + id)}" data-stitle="${esc(title)}" data-shref="${esc(href)}" aria-pressed="${on}" aria-label="${on ? 'Remove from saved' : 'Save'}" title="${on ? 'Saved' : 'Save'}"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M6 3h12v18l-6-4.5L6 21z" fill="${on ? 'currentColor' : 'none'}" stroke="currentColor" stroke-width="2.2" stroke-linejoin="round"/></svg></button>`; };
async function toggleSave(id, title, href) { let l = saved(); if (l.some(x => x.id === id)) l = l.filter(x => x.id !== id); else l.unshift({ id, title, href, type: id.split(':')[0], at: Date.now() }); store.set('saved', l.slice(0, 200)); if (db && me) { try { await db.collection('data/users/' + me).doc('saved').set({ items: l, at: Date.now() }); } catch (e) { } } }
const SAVE_T = { role: 'Volunteer role', fund: 'Fund', deal: 'Discount', service: 'Service', event: 'Event', need: 'Need' };
function nudges() {
  if (!profile) return [];
  const al = profile.alerts || { causes: [], types: [] }, out = [];
  const causes = al.causes || [];
  (window.FUNDS || []).filter(f => f.st !== 'closed' && (!causes.length || f.c.some(c => causes.includes(c)))).filter(f => fSoon(f) || f.st === 'open').sort((a, z) => (fSoon(z) - fSoon(a))).slice(0, 3).forEach(f => out.push({ k: 'Fund', t: f.n, d: (fSoon(f) ? 'Closing ' + new Date(f.dl).toLocaleDateString('en-GB', { day: 'numeric', month: 'short' }) + ' · ' : '') + (f.at || '').split(/[;(]/)[0], h: 'funding' }));
  liveNeeds().filter(n => isNewTs(n.at)).slice(0, 2).forEach(n => out.push({ k: 'Urgent need', t: n.title, d: (n.org || '') + (n.deadline ? ' · by ' + new Date(n.deadline).toLocaleDateString('en-GB', { day: 'numeric', month: 'short' }) : ''), h: 'needs' }));
  const tabs = (al.types || []).map(t => ({ school: 'tea', nhs: 'nhs', charity: 'cha', care: 'car', youth: 'stu', faith: 'cha', emergency: 'emg' }[t])).filter(Boolean);
  if (tabs.length) { const n = (window.DEALS || []).filter(x => x.tabs.some(t => tabs.includes(t))).length; out.push({ k: 'Discounts', t: n + ' discounts for your team', d: 'Matched to the people you told us about', h: 'discounts' }); }
  return out;
}

