const mdLite = md => { const lines = esc(md).split('\n'); let h = '', tbl = []; const flush = () => { if (tbl.length) { const r = tbl.filter(l => !/^\|\s*-/.test(l)).map(l => l.replace(/^\||\|$/g, '').split('|')); h += `<div class="scroll"><table class="dtab"><thead><tr>${r[0].map(c => `<th>${c.trim()}</th>`).join('')}</tr></thead><tbody>${r.slice(1).map(x => `<tr>${x.map(c => `<td>${c.trim().replace(/(https?:\/\/[^\s<)]+)/g, '<a href="$1" target="_blank" rel="noopener">$1</a>')}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`; tbl = []; } };
  for (const l of lines) { if (/^\|/.test(l)) { tbl.push(l); continue; } flush(); const t = l.replace(/`([^`]+)`/g, '<code>$1</code>').replace(/\*\*([^*]+)\*\*/g, '<b>$1</b>').replace(/(^|\s)(https?:\/\/[^\s<)]+)/g, '$1<a href="$2" target="_blank" rel="noopener">$2</a>'); h += /^### /.test(l) ? `<h4>${t.slice(4)}</h4>` : /^## /.test(l) ? `<h3>${t.slice(3)}</h3>` : /^# /.test(l) ? `<h2>${t.slice(2)}</h2>` : /^\s*[-*] /.test(l) ? `<li>${t.replace(/^\s*[-*] /, '')}</li>` : l.trim() ? `<p>${t}</p>` : ''; } flush(); return h; };
