  const T = (x, y, s, str, wt = 800, fill = '#fff', anchor = 'start') => `<text x="${x.toFixed(1)}" y="${y.toFixed(1)}" font-family="Plus Jakarta Sans,Arial,sans-serif" font-weight="${wt}" font-size="${s.toFixed(1)}" fill="${fill}" text-anchor="${anchor}">${esc(str)}</text>`;
  const block = (x, y, fitr, lh = 1.08, wt = 800, fill = '#fff') => fitr.lines.map((l, i) => T(x, y + fitr.s * (i + 1) * lh - fitr.s * .2, fitr.s, l, wt, fill)).join('');
