    body += `<g opacity="${op}" transform="translate(${-slide} 0)">${T(pad, y + w * .04, w * .04, k.org, 700, '#ffffffcc')}${block(pad, y + w * .06, tt)}</g>`;
    y += w * .06 + tt.s * tt.lines.length * 1.08 + w * .05;
    const dt = fit(k.date, w * .065, iw, 2); body += `<g transform="translate(${pad} ${y}) scale(${pulse}) translate(${-pad} ${-y})">${block(pad, y, dt, 1.1, 800, k.c2)}</g>`; y += dt.s * dt.lines.length * 1.1 + w * .02;
    if (f !== 'roller' && f !== 'ig') { const vn = fit(k.venue, w * .036, iw, 2); body += block(pad, y, vn, 1.2, 600, '#ffffffe0'); y += vn.s * vn.lines.length * 1.2 + w * .03; }
    if (k.feat && !['roller', 'ig', 'tiktok'].includes(f)) { const fs = w * .032, fwid = Math.min(iw, k.feat.length * fs * .56 + fs * 2); body += `<rect x="${pad}" y="${y}" width="${fwid}" height="${fs * 2}" rx="${fs}" fill="#ffffff26"/>${T(pad + fs, y + fs * 1.35, fs, k.feat, 700)}`; y += fs * 2 + w * .035; }
