/* ---------- campaign questionnaire ---------- */
const TIERS = [
  ['ess', 'Essentials', 'For a single event or short campaign', ['One consistent look for the campaign', 'Posts and stories for your main platforms', 'A poster or leaflet', 'Captions written for you', 'Mock-ups before anything goes out']],
  ['camp', 'Campaign', 'Our recommendation for most campaigns', ['Everything in Essentials', 'Different media for each audience', 'A month marketing plan and posting schedule', 'Every format, including TikTok and animated versions', 'Print: banners, roller banners, cards, clothing', 'Language and accessible versions', 'Help scheduling your posts']],
  ['full', 'Full system', 'For programmes that run for months', ['Everything in Campaign', 'Automated posts that make and send themselves', 'Fundraising and sign-up pages', 'Sponsor call-out and sponsor pack or deck', 'Certificates and thank-yous', 'Video scripts, filming or a training day', 'Reviews and advice while it runs']],
];
const AUD_GETS = [['Everyone', 'An announcement that explains the programme and raises awareness'], ['People who’ll benefit', 'How to access it and who’s eligible, in plain words'], ['Volunteers', 'A call-out with roles, times and what they’ll gain'], ['Donors & supporters', 'An appeal, progress updates and thank-yous'], ['Sponsors & local businesses', 'A sponsor call-out and a sponsor pack or deck: the cause, what they get, past results'], ['Partners & schools', 'Sign-up posts, progress posts and certificates'], ['Communities who speak other languages', 'Translated versions'], ['Older people & accessibility', 'Large-print, easy-read and subtitled versions']];
const chk = (name, items) => `<div class="checks">${items.map(i => `<label><input type="checkbox" name="${name}" value="${esc(i)}">${esc(i)}</label>`).join('')}</div>`;
V.brief = id => {
  const c = C.C.find(x => x.id === id);
  const tier = id === 'system' ? 'full' : '';
  return `<div class="wrap">${back('studio', 'Design & Print Studio', 'Plan a campaign with us')}<h1>Plan a campaign with us</h1>
  <p style="max-width:44em">Answer a few questions about your campaign and who it’s for. We’ll come back with a plan, a campaign pack built for every audience, and a quote at Community Hub concession rates. No payment now.</p>
  <h2 style="margin-top:22px">Choose how much you’d like us to do</h2>
  <div class="grid">${TIERS.map(([k, n, d, l]) => `<div class="tier${k === 'camp' ? ' mid' : ''}"><h3 style="margin:0">${n}</h3><span class="note">${d}</span><ul>${l.map(x => `<li>${esc(x)}</li>`).join('')}</ul></div>`).join('')}</div>
  <details class="dlbox" style="margin-top:16px"><summary style="cursor:pointer"><b>What you’ll get for each audience</b></summary><div class="grid tight" style="margin-top:12px">${AUD_GETS.map(([a, b]) => `<div><b>${esc(a)}</b><div class="note">${esc(b)}</div></div>`).join('')}</div>
  <p style="margin-top:12px"><b>Video:</b> scripts and scene-by-scene plans (what’s said, what’s shown, who’s in it), a filming day where we record everything in one go, or a training day that shows your team how to film well, with us editing or teaching you to edit.</p></details>
  <form class="form qs" id="qForm" style="margin-top:18px">
  <fieldset><legend>1. Your campaign</legend>
  <label class="f">Start from an example campaign (optional)<select class="in" name="example" onchange="if(this.value)location.hash='brief-'+this.value"><option value="">Choose one…</option>${C.C.map(x => `<option value="${x.id}"${c?.id === x.id ? ' selected' : ''}>${esc(x.t)}</option>`).join('')}</select></label>
  <div class="two"><label class="f">Campaign or programme name<input class="in" name="name" required value="${esc(c ? c.t : '')}"></label><label class="f">Organisation<input class="in" name="org" required value="${esc(profile?.org || '')}"></label></div>
  <div class="two"><label class="f">Dates<input class="in" name="dates" placeholder="e.g. 1 Dec to 28 Feb, or Sat 14 March 11am"></label><label class="f">When do you need the first piece?<input class="in" type="date" name="deadline"></label></div>
  <b style="font-size:15px">What do you want it to do?</b>${chk('goals', ['Raise money', 'Get people to an event', 'Recruit volunteers', 'Help people access a service', 'Find sponsors', 'Inform parents or the community', 'Celebrate'])}</fieldset>
  <fieldset><legend>2. Who needs to see it?</legend>${chk('aud', ['People who’d benefit', 'Donors & supporters', 'Volunteers', 'Sponsors & local businesses', 'Partners & other organisations', 'Schools', 'Parents & carers', 'Young people', 'Older people', 'Faith communities', 'The wider community'])}
  <label class="f" style="margin-top:12px">Who can take part or get help? (eligibility)<textarea class="in" name="eligibility" placeholder="e.g. Families in Luton on a low income. Referral needed from a school or GP."></textarea></label></fieldset>
  <fieldset><legend>3. Where will they see it?</legend>${chk('ch', ['Instagram', 'Facebook page', 'Local Facebook groups', 'WhatsApp groups & Status', 'TikTok', 'LinkedIn', 'Email or newsletter', 'Your website', 'Posters & noticeboards', 'Letters home / school apps', 'Leaflets door to door', 'Events & stalls'])}</fieldset>
  <fieldset><legend>4. Languages & access</legend><b style="font-size:15px">Languages besides English</b>${chk('lang', ['Urdu', 'Bengali', 'Punjabi', 'Gujarati', 'Arabic', 'Polish', 'Romanian', 'Somali'])}
  <b style="font-size:15px;display:block;margin-top:12px">Access needs</b>${chk('acc', ['Large print (e.g. older people)', 'Easy-read version', 'High contrast', 'Subtitled videos', 'Voice notes or audio'])}</fieldset>
  <fieldset><legend>5. What would you like?</legend>${chk('want', ['Instagram posts & stories', 'TikTok', 'Animated versions', 'Posters', 'Leaflets', 'Roller or vinyl banners', 'Business cards', 'Newsletter pieces', 'Certificates', 'Clothing & hoodies', 'Sponsor pack or deck', 'Fundraising or sign-up page', 'Automated posts'])}
  <b style="font-size:15px;display:block;margin-top:12px">Video</b>${chk('video', ['Video scripts & scene plans', 'A filming day with us', 'A training day for our team', 'Editing our footage'])}
  <label class="f" style="margin-top:12px">Level<select class="in" name="tier"><option value="">Not sure yet</option>${TIERS.map(([k, n]) => `<option${k === tier ? ' selected' : ''}>${n}</option>`).join('')}</select></label></fieldset>
  <fieldset><legend>6. The message</legend>
  <label class="f">What do you want people to know?<textarea class="in" name="msg">${esc(c ? c.msg.join('\n') : '')}</textarea></label>
  <label class="f">The one thing people must remember<small>We’ll make this biggest on every piece, e.g. the date or the donate link</small><input class="in" name="remember"></label>
  <div class="two"><label class="f">Target (optional)<input class="in" name="target" placeholder="e.g. £5,000 for 250 food parcels"></label><label class="f">Link for the QR code<input class="in" name="link" placeholder="https://"></label></div>
  <label class="f">Logos & photos<small>You can also send them on WhatsApp</small><input class="in" type="file" name="files" multiple accept="image/*,.pdf,.ai,.eps,.svg"></label>
  <label class="f">Anything else?<textarea class="in" name="extra"></textarea></label></fieldset>
  <button class="btn p">${ic('brief')} Send my answers</button><p class="note">We’ll reply with a plan and a quote at Community Hub concession rates. Mock-ups always come first.</p></form></div>`;
};

/* ---------- automated campaign systems ---------- */
let sysDemo = { school: 'Example Primary School', raised: 640, target: 1500, week: 3 };
function sysPost(kind) {
  const d = sysDemo, pct = Math.min(100, Math.round(d.raised / Math.max(1, d.target) * 100));
  const head = { join: 'Thank you for joining!', week: `Week ${d.week} update`, end: 'Thank you!' }[kind];
  const body = { join: `${d.school} has signed up to the Winter Food Appeal`, week: `${d.school} has raised £${d.raised.toLocaleString('en-GB')}`, end: `${d.school} raised £${d.raised.toLocaleString('en-GB')} for local families` }[kind];
  return `<svg viewBox="0 0 400 400" role="img" aria-label="${esc(head)}"><rect width="400" height="400" fill="#f4f1ea"/><rect x="0" y="0" width="400" height="92" fill="#2f6b4f"/>
  <text x="24" y="40" font-family="Plus Jakarta Sans,Arial" font-weight="700" font-size="15" fill="#e8dcc0">WINTER FOOD APPEAL · EXAMPLE CHARITY</text><text x="24" y="72" font-family="Plus Jakarta Sans,Arial" font-weight="800" font-size="24" fill="#fff">${esc(head)}</text>
  <rect x="24" y="116" width="96" height="96" rx="14" fill="#fff" stroke="#ddd6c6"/><text x="72" y="172" text-anchor="middle" font-family="Plus Jakarta Sans,Arial" font-weight="800" font-size="30" fill="#2f6b4f">${esc(initials(d.school))}</text><text x="72" y="228" text-anchor="middle" font-family="Arial" font-size="10" fill="#777">school logo</text>
  <foreignObject x="136" y="116" width="240" height="110"><div xmlns="http://www.w3.org/1999/xhtml" style="font:700 19px/1.3 Atkinson Hyperlegible,Arial,sans-serif;color:#1d1b25">${esc(body)}</div></foreignObject>
  ${kind !== 'join' ? `<rect x="24" y="262" width="352" height="18" rx="9" fill="#ddd6c6"/><rect x="24" y="262" width="${3.52 * pct}" height="18" rx="9" fill="#2f6b4f"/><text x="24" y="304" font-family="Arial" font-size="14" fill="#555">${pct}% of the £${d.target.toLocaleString('en-GB')} school target</text>` : `<text x="24" y="282" font-family="Arial" font-size="15" fill="#555">Every pound buys food for Luton families this winter.</text>`}
  <rect x="24" y="330" width="352" height="46" rx="12" fill="#2f6b4f"/><text x="200" y="359" text-anchor="middle" font-family="Plus Jakarta Sans,Arial" font-weight="800" font-size="16" fill="#fff">${kind === 'end' ? 'Certificate on its way' : 'Support us: link in bio'}</text></svg>`;
}
V.systems = () => `<div class="wrap">${back('studio', 'Design & Print Studio', 'Automated campaign systems')}<h1>Automated campaign systems</h1>
  <p style="max-width:44em">For programmes that run for weeks or months, we build a system that makes your branded posts and sends them out for you: on time, on every platform, and to your partners. You can still add things by hand whenever you like.</p>
  <section class="band"><h2>Example: a schools fundraising programme</h2><div class="steps">${[['A school signs up', 'A “Thank you for joining” post with the school’s logo is made and posted automatically.'], ['Every Monday', 'Each school gets a progress post showing what it’s raised. It’s sent to the school and posted on your socials.'], ['Linked up', 'Everything connects to your fundraising page and sign-up links, so totals and links are always right.'], ['At the end', 'Thank-you posts and certificates for every school, ready to go.']].map(([b, t]) => `<div><b>${b}</b><span>${t}</span></div>`).join('')}</div></section>
  <section class="band" style="padding-top:0"><div class="sec-h"><div><h2>Try it <span class="tag ex">Example</span></h2><p>Change the details and watch the posts update. This is a demo with made-up figures.</p></div></div>
  <form class="form" id="sysForm"><div class="two"><label class="f">School name<input class="in" name="school" value="${esc(sysDemo.school)}"></label><label class="f">Week<input class="in" type="number" min="1" max="12" name="week" value="${sysDemo.week}"></label></div><div class="two"><label class="f">Raised so far (£)<input class="in" type="number" min="0" name="raised" value="${sysDemo.raised}"></label><label class="f">School target (£)<input class="in" type="number" min="1" name="target" value="${sysDemo.target}"></label></div></form>
  <div class="grid" id="sysOut" style="margin-top:16px">${sysCards()}</div></section>
  <div class="feature"><h2>Get a system like this</h2><p>Tell us about your programme and we’ll design the system, the look and the schedule around it. Community Hub concession rates.</p><div class="row"><a class="btn p" href="#brief-system">Get a system like this</a><a class="btn o" href="#review">Free campaign review</a></div></div></div>`;
const sysCards = () => [['join', 'When a school signs up', 'Posted on your Instagram and Facebook, and sent to the school'], ['week', 'Every Monday at 9am', 'Sent to the school and posted on all your platforms'], ['end', 'When the programme ends', 'Thank-you post and certificate for each school']].map(([k, t, w]) => `<div class="auto-post">${sysPost(k)}<div class="when"><b>${t}</b><br>${w}</div></div>`).join('');

/* ---------- why it matters ---------- */
V.why = () => `<div class="wrap">${back('home', 'Home', 'Why it matters')}<h1>Do more good with what you’re trusted with</h1>
  <p style="max-width:44em">People give your organisation their money and their time because they trust you to use it well. Every hour spent chasing messages, remaking posters and fixing links is an hour not spent on the people you’re there for.</p>
  ${faithNote()}
  <section class="band"><h2>The problem</h2><ul class="ticks"><li>Chasing people on WhatsApp, sending emails, designing a poster, making a link page and a JustGiving page, sharing links, then fixing mistakes.</li><li>Remaking the Instagram post in a different size for a banner, then again for a leaflet.</li><li>Paying freelancers by the day, or paying platforms commission you don’t need to.</li><li>Posts going out irregularly, on some platforms and not others, so the people who need them miss them. A winter tips series only helps if people actually see it, every week, wherever they are.</li></ul></section>
  <section class="band" style="padding-top:0"><h2>The fix</h2><p>One place that does the repetitive work for you, consistently and professionally, at concession rates. Your staff and volunteers get their time back for the work on the ground. You reach more people and raise more.</p><div class="grid tight">${['admin', 'grants', 'volunteers', 'small'].map(statCard).join('')}</div></section>
  <section class="band" style="padding-top:0"><h2>Consistency builds trust</h2><p>When every poster, post and banner looks like it comes from the same organisation, people recognise you, remember you and trust you more.</p><div class="grid tight">${['brand', 'visibility', 'trust'].map(statCard).join('')}</div></section>
  <section class="band" style="padding-top:0"><h2>Why quick AI-made posters fall short</h2><p>They’re fast, but they tend to look like everyone else’s because they’re built from styles that already exist. They’re hard to resize cleanly, can be labelled as AI-generated on social media, and rarely match from one post to the next. Doing it all in Canva or Photoshop yourself takes hours you don’t have.</p><div class="grid tight">${['aitrust', 'digital'].map(statCard).join('')}</div></section>
  <section class="band" style="padding-top:0"><h2>One poster isn’t enough</h2><p>A campaign has to reach different people in different places: beneficiaries, donors, volunteers, sponsors, partners. Some read Urdu or Polish, some need bigger type, some are only in a local Facebook group. That’s why we ask who it’s for and make the right media for each of them.</p></section>
  <div class="feature"><h2>See what you could save</h2><p>Start with a free review of a campaign you’re running or planning.</p><div class="row"><a class="btn p" href="#review">Free campaign review</a><a class="btn o" href="#brief">Plan a campaign with us</a></div></div></div>`;

