function searchAll(q) {
  if (!q) return;
  const res = [];
  H.DIR.forEach(o => (o.n + ' ' + o.sub + ' ' + o.a).toLowerCase().includes(q) && res.push(['Directory', o.n, '#org-' + o.id]));
  HELP.forEach(s => (s.n + ' ' + s.org + ' ' + s.help).toLowerCase().includes(q) && res.push(['Community Support', s.n, '#help']));
  VOL.forEach(v => (v.t + ' ' + v.org + ' ' + v.d).toLowerCase().includes(q) && res.push(['Volunteering', v.t, '#volunteering']));
  H.EV.forEach(v => (v.t + ' ' + v.d).toLowerCase().includes(q) && res.push(['Event', v.t, '#events']));
  H.WO.forEach(v => (v.t + ' ' + v.d).toLowerCase().includes(q) && res.push(['Activity', v.t, '#activities']));
  (window.FUNDS || []).forEach(v => (v.n + ' ' + v.by + ' ' + v.cr).toLowerCase().includes(q) && res.push(['Funding', v.n, '#funding']));
  C.C.forEach(v => (v.t + ' ' + v.d).toLowerCase().includes(q) && res.push(['Campaign', v.t, '#camp-' + v.id]));
  ALL.forEach(a => (a[1] + ' ' + a[3]).toLowerCase().includes(q) && res.push(['Tool', a[1], '#' + a[0]]));
  modal(`<div class="mhead"><h3>${res.length} results for “${esc(q)}”</h3><button class="ib" data-close>${ic('x')}</button></div><div style="display:grid;gap:6px">${res.slice(0, 60).map(([k, t, h]) => `<a class="tile" href="${h}" data-close><div><span>${k}</span><b>${esc(t)}</b></div></a>`).join('') || '<div class="empty">Nothing found. Try a simpler word.</div>'}</div>`);
}
async function aiWrite(f) {
  const o = formData(f), out = $('#aiOut'); out.innerHTML = '<div class="dlbox">Writing…</div>';
  let s = null; try { s = await claude.use('sample'); } catch (e) { }
  if (!s) { out.innerHTML = '<div class="dlbox">The writer isn’t available in this view. On the live hub it runs for every signed-in member.</div>'; return; }
  const prompt = `You write short, ready-to-post wording for a ${o.tone.toLowerCase()} UK community organisation${o.org ? ' called ' + o.org : ''} in Luton. Write a ${o.kind}. Facts (use only these, don't invent figures, names or dates): ${o.about}\nRules: British English, plain words, no hashtag spam (max 4 relevant hashtags for social), include a clear call to action. For WhatsApp keep it under 70 words. Give two versions labelled Version 1 and Version 2. Output plain text only.`;
  try { const r = await s(prompt, { modelTier: 'quick', onText: ({ text }) => { out.innerHTML = `<div class="dlbox"><div class="msg" id="aiTxt" style="max-height:none">${esc(text)}</div></div>`; } }); out.innerHTML = `<div class="dlbox"><div class="msg" id="aiTxt" style="max-height:none">${esc(r.text)}</div><div class="row" style="margin-top:10px"><button class="btn p sm" data-copy="#aiTxt">${ic('copy')} Copy</button></div><p class="note">Check names, dates and amounts before posting.</p></div>`; }
  catch (e) { out.innerHTML = `<div class="dlbox">${e.code === 'rate_limited' ? 'Lots of people are writing right now. Try again in a minute.' : 'Couldn’t write that just now.'}</div>`; }
}

