  const forms = Object.entries(store.get('fresp', {})).flatMap(([fid, rs]) => rs.filter(r => !r.ex).map(r => ({ id: 'f' + r.at, t: 'form', title: 'New response: ' + ((store.get('forms', []).find(f => f.id === fid) || {}).title || 'your form'), body: '', at: r.at, st: r.read ? 'done' : 'new', h: 'formres-' + fid })));
  const jobs = store.get('mine', []).filter(s => /design|brief|free-post|campaign|link-page|oms|funded/.test(s.kind)).map(s => ({ id: 'j' + s.at, t: 'job', title: kindLabel(s.kind) + ': received', body: 'We’ll update you here as it moves along.', at: s.at, st: 'done' }));
  const rd = store.get('inbread', {});
  return [...own, ...vol, ...forms, ...jobs].map(x => ({ ...x, st: rd[x.id] || x.st })).sort((a, b) => b.at - a.at);
