document.addEventListener('submit', e => { if (e.target.id !== 'ffForm') return; e.preventDefault(); e.stopImmediatePropagation(); const fm = e.target, f = fGet(fm.dataset.id), fd = new FormData(fm); const a = f.qs.map((x, i) => x.t === 'cb' ? fd.getAll('q' + i) : ['rate', 'emoji', 'nps', 'num'].includes(x.t) ? (fd.get('q' + i) === '' || fd.get('q' + i) == null ? '' : +fd.get('q' + i)) : fd.get('q' + i) || ''); const r = store.get('fresp', {}); (r[f.id] = r[f.id] || []).push({ at: Date.now(), a, name: fd.get('_name') || '' }); store.set('fresp', r); $('#main .card').innerHTML = `<h1 style="font-size:28px">${esc(f.thanks)}</h1><p class="note">Your answers have been sent.</p><a class="btn s" href="#formres-${f.id}">See results</a><p class="pow">Powered by ${SMRL}</p>`; }, true);
let fFrom = '', fTo = '';
const topWords = l => { const stop = new Set('the and for with was are but you our not this that have more very really were they them what from just into some about there would could please much would been also very'.split(' ')); const c = {}; l.join(' ').toLowerCase().replace(/[^a-z\s']/g, ' ').split(/\s+/).filter(w => w.length > 3 && !stop.has(w)).forEach(w => c[w] = (c[w] || 0) + 1); return Object.entries(c).sort((a, b) => b[1] - a[1]).slice(0, 12); };
const fStats = (f, rs) => f.qs.map((x, i) => { const v = rs.map(r => r.a[i]).filter(a => a !== '' && a != null && !(Array.isArray(a) && !a.length)); const out = { x, n: v.length }; if (['rate', 'emoji', 'num', 'nps'].includes(x.t)) { out.avg = v.length ? v.reduce((t, n) => t + +n, 0) / v.length : 0; } if (x.t === 'nps' && v.length) { const pr = v.filter(n => n >= 9).length, de = v.filter(n => n <= 6).length; out.nps = Math.round((pr - de) / v.length * 100); } if (['mc', 'dd', 'yn', 'cb', 'rate', 'emoji', 'nps'].includes(x.t)) { const opts = x.t === 'yn' ? ['Yes', 'No'] : x.t === 'rate' || x.t === 'emoji' ? ['1', '2', '3', '4', '5'] : x.t === 'nps' ? [...Array(11)].map((_, k) => String(k)) : x.o; out.bars = opts.map(o => [o, v.filter(a => Array.isArray(a) ? a.includes(o) : String(a) === o).length]); } if (['long', 'short'].includes(x.t)) { out.words = topWords(v); out.recent = v.slice(-3).reverse(); } return out; });
V.formres = id => { const f = fGet(id); if (!f) return `<div class="wrap">${back('forms', 'Forms & feedback')}<div class="empty">Form not found on this device.</div></div>`;
  const all = fresp(id), rs = all.filter(r => (!fFrom || ISO(new Date(r.at)) >= fFrom) && (!fTo || ISO(new Date(r.at)) <= fTo)), st = fStats(f, rs), ex = all.some(r => r.ex);
  const wk = {}; rs.forEach(r => { const d = new Date(r.at); d.setDate(d.getDate() - d.getDay()); const k = ISO(d); wk[k] = (wk[k] || 0) + 1; }); const wks = Object.entries(wk).sort(), mx = Math.max(1, ...wks.map(w => w[1]));
  const npsQ = st.find(s => s.nps != null), avgQ = st.find(s => s.avg != null && s.x.t !== 'nps');
  return `<div class="wrap" id="frep">${back('forms', 'Forms & feedback', 'Results')}<h1>${esc(f.title)}: results</h1>${ex ? '<p><span class="tag ex">Example</span> <span class="note">Example responses are mixed in so you can see how results look. They disappear from your Inbox and are never counted as real.</span></p>' : ''}
  <div class="row noprint" style="margin:10px 0 16px"><label class="f" style="font-size:14px">From<input class="in" type="date" id="fFrom" value="${fFrom}"></label><label class="f" style="font-size:14px">To<input class="in" type="date" id="fTo" value="${fTo}"></label><button class="btn s sm" data-fcsv="${id}">${ic('dl')} CSV</button><button class="btn s sm" data-fprint>Printable report</button><button class="btn p sm" data-fimpact="${id}">Add to Impact report</button></div>
  <div class="grid tight"><div class="stat"><b>${rs.length}</b><p>Responses</p></div>${avgQ ? `<div class="stat"><b>${avgQ.avg.toFixed(1)}</b><p>Average: ${esc(avgQ.x.l)}</p><small>Out of 5</small></div>` : ''}${npsQ ? `<div class="stat"><b>${npsQ.nps > 0 ? '+' : ''}${npsQ.nps}</b><p>Recommend score</p><small>% who’d recommend (9–10) minus % who wouldn’t (0–6)</small></div>` : ''}</div>
  ${wks.length > 1 ? `<div class="dlbox" style="margin-top:14px"><h3>Responses over time</h3><svg viewBox="0 0 ${wks.length * 40} 90" style="width:100%;height:auto" role="img" aria-label="Responses per week">${wks.map(([k, n], i) => `<rect x="${i * 40 + 8}" y="${80 - n / mx * 70}" width="24" height="${n / mx * 70}" rx="5" fill="var(--blue)"/><text x="${i * 40 + 20}" y="${76 - n / mx * 70}" font-size="10" text-anchor="middle" fill="currentColor">${n}</text>`).join('')}</svg><p class="note">Each bar is one week.</p></div>` : ''}
  <div style="display:grid;gap:14px;margin-top:14px">${st.filter(s => s.x.t !== 'section').map(s => `<div class="dlbox"><h3>${esc(s.x.l)}</h3><p class="note">${s.n} answer${s.n === 1 ? '' : 's'}${s.avg != null ? ' · average ' + s.avg.toFixed(1) : ''}</p>${s.bars ? `<div class="bars">${s.bars.map(([o, n]) => `<div class="br"><span>${s.x.t === 'emoji' ? ['😞', '🙁', '😐', '🙂', '😄'][+o - 1] : esc(o)}</span><span class="bt"><i style="width:${s.n ? n / s.n * 100 : 0}%"></i></span><b>${n}</b></div>`).join('')}</div>` : ''}${s.words ? `${s.words.length ? `<p class="note" style="margin:6px 0 4px">Top words</p><div class="words">${s.words.map(([w, n]) => `<span style="font-size:${13 + n * 2}px">${esc(w)}</span>`).join('')}</div>` : ''}${s.recent.length ? `<ul style="margin:8px 0 0;padding-left:18px">${s.recent.map(t => `<li>${esc(t)}</li>`).join('')}</ul>` : ''}` : ''}${['date'].includes(s.x.t) ? '' : ''}</div>`).join('')}</div>
  <p class="pow">Powered by ${SMRL}</p></div>`; };
document.addEventListener('change', e => { if (e.target.id === 'fFrom' || e.target.id === 'fTo') { fFrom = $('#fFrom').value; fTo = $('#fTo').value; render(); } });
document.addEventListener('click', e => { const b = e.target.closest('[data-fcsv],[data-fprint],[data-fimpact]'); if (!b) return;
  if (b.dataset.fcsv) { const f = fGet(b.dataset.fcsv), rs = fresp(f.id); const cell = v => '"' + String(Array.isArray(v) ? v.join('; ') : v ?? '').replace(/"/g, '""') + '"'; const csv = [['Date', 'Example', ...(f.anon ? [] : ['Name']), ...f.qs.filter(x => x.t !== 'section').map(x => x.l)].map(cell).join(','), ...rs.map(r => [new Date(r.at).toLocaleString('en-GB'), r.ex ? 'yes' : '', ...(f.anon ? [] : [r.name]), ...f.qs.map((x, i) => x.t === 'section' ? null : r.a[i]).filter((v, i) => f.qs[i].t !== 'section')].map(cell).join(','))].join('\n'); saveBlob(new Blob([csv], { type: 'text/csv' }), slugify(f.title) + '-results.csv'); }
  if ('fprint' in b.dataset) { document.body.classList.add('printing-rep'); setTimeout(() => { print(); document.body.classList.remove('printing-rep'); }, 50); }
  if (b.dataset.fimpact) { const f = fGet(b.dataset.fimpact), st = fStats(f, fresp(f.id).filter(r => !r.ex)), a = st.find(s => s.avg != null && s.x.t !== 'nps'), n = st.find(s => s.nps != null); const lines = store.get('impactAdd', []); lines.push(`${f.title}: ${fresp(f.id).filter(r => !r.ex).length} responses${a ? `, average ${a.avg.toFixed(1)}/5 for “${a.x.l}”` : ''}${n ? `, recommend score ${n.nps}` : ''}`); store.set('impactAdd', lines); toast('Added to your Impact report'); }
});

