const CHECKED = '24 November 2026';

/* ---------- first-party, cookie-free analytics ---------- */
const SID = Math.random().toString(36).slice(2) + Date.now().toString(36); /* memory only, gone when the page closes */
const AQ = []; let aTimer = null;
const srcOf = () => { const u = new URLSearchParams(location.search), r = document.referrer || ''; if (u.get('utm_source')) return u.get('utm_source').toLowerCase().slice(0, 30); if (/instagram/i.test(r)) return 'instagram'; if (/whatsapp|wa\.me/i.test(r)) return 'whatsapp'; if (/google\./i.test(r)) return 'google'; if (/facebook|fb\./i.test(r)) return 'facebook'; if (/tiktok/i.test(r)) return 'tiktok'; return r ? 'other' : 'direct'; };
const SRC = srcOf(), UTM = Object.fromEntries([...new URLSearchParams(location.search)].filter(([k]) => /^utm_/.test(k)).map(([k, v]) => [k, v.slice(0, 40)]));
const DEV = innerWidth < 700 ? 'mobile' : innerWidth < 1100 ? 'tablet' : 'desktop';
const anonTerm = t => String(t || '').toLowerCase().replace(/[\w.+-]+@[\w-]+\.[\w.]+/g, '[email]').replace(/\b\d[\d\s]{6,}\b/g, '[number]').replace(/\b[a-z]{1,2}\d{1,2}[a-z]?\s*\d[a-z]{2}\b/gi, '[postcode]').slice(0, 60);
const track = (ev, p = {}) => { try { AQ.push({ ev, p, r: route().v, s: SID, src: SRC, utm: UTM, dev: DEV, org: profile && !profile.pending ? profile.orgId || null : null, t: Date.now() }); clearTimeout(aTimer); aTimer = setTimeout(flushA, 1500); } catch (e) { } };
let aBusy = false; async function flushA() { if (!AQ.length || !db || !me || aBusy) return; aBusy = true; const batch = AQ.splice(0); try { const ref = db.collection('analytics').doc(me), cur = await ref.get(), ev = ((cur && cur.exists && cur.data().events) || []).concat(batch).slice(-800); await ref.set({ at: Date.now(), events: ev }); } catch (e) { } aBusy = false; }
addEventListener('pagehide', flushA);
let lastPv = '';
const pv = () => { const r = route(); if (r.h === lastPv) return; lastPv = r.h; track('page_view', { id: r.id ? (r.v === 'org' || r.v === 'appeal' ? r.id : '') : '' }); };
const CTA = { design: 'design_print_click', xq: 'request_open', fnew: 'form_created', join: 'signup_started', dlogo: '', bdl: '' };
document.addEventListener('click', e => { const a = e.target.closest('a,button'); if (!a) return; const d = a.dataset;
  if (a.matches('a[href^="http"]') && !a.href.includes(location.host)) track('outbound', { host: (() => { try { return new URL(a.href).host; } catch (er) { return ''; } })(), deal: !!a.closest('.deal') });
  if (a.matches('a[href="#studio"],a[href="#brief"]')) track('design_print_click', { to: a.getAttribute('href').slice(1) });
  if (d.xq) track(d.xq === 'oms-demo' ? 'book_demo_click' : d.xq === 'verify-claim' ? 'claim_started' : 'request_open', { kind: d.xq });
  if ('join' in d) track('signup_started');
  if (a.closest('.slide') && a.matches('a')) track('promo_click', { to: a.getAttribute('href') });
  if (a.closest('.lp a.lb')) track('linkpage_button', {});
}, true);
document.addEventListener('submit', e => { const f = e.target, id = f.id;
  const map = { joinForm: 'signup_completed', briefForm: 'questionnaire_submitted', qForm: 'questionnaire_submitted', appealForm: 'appeal_created', ffForm: 'form_response', xqForm: 'request_sent', lpForm: 'linkpage_saved', fundQuiz: 'funding_quiz_done', calForm: 'calendar_post', polForm: 'policy_check' };
  if (map[id]) track(map[id], id === 'xqForm' ? { kind: f.dataset.kind } : {});
  if (id === 'hsearch') { const q = new FormData(f).get('q') || ''; setTimeout(() => track('search', { q: anonTerm(q), zero: !!$('#main .empty') && !$('#main .card') }), 300); }
}, true);
document.addEventListener('focusin', e => { const f = e.target.closest('form'); if (f && ['briefForm', 'qForm'].includes(f.id) && !f.dataset.started) { f.dataset.started = 1; track('questionnaire_started'); } });

/* owner analytics dashboard */
let AN = null, anDays = 30;
async function loadAnalytics() { if (!db || !isOwner) { AN = []; return; } try { const s = await db.collection('analytics').get(); AN = s.docs.flatMap(d => d.data().events || []); } catch (e) { AN = []; } render(); }
const anSample = () => { const out = [], pages = ['home', 'help', 'funding', 'directory', 'discounts', 'studio', 'linkpage', 'forms', 'prayer', 'training', 'alltools', 'calendar'], srcs = ['instagram', 'whatsapp', 'google', 'direct', 'facebook', 'other']; for (let i = 0; i < 900; i++) { const t = Date.now() - Math.random() * 30 * 864e5, s = 'x' + Math.floor(i / 4); out.push({ ev: 'page_view', r: pages[Math.floor(Math.random() ** 1.6 * pages.length)], s, src: srcs[Math.floor(Math.random() ** 1.4 * srcs.length)], dev: Math.random() > .3 ? 'mobile' : 'desktop', t, org: Math.random() > .85 ? H.DIR[Math.floor(Math.random() * 20)].id : null, ex: 1 }); } [['signup_started', 60], ['signup_completed', 24], ['questionnaire_started', 40], ['questionnaire_submitted', 13], ['outbound', 120], ['design_print_click', 70], ['promo_click', 18], ['logo_hd_download', 30], ['form_created', 9], ['search', 140]].forEach(([ev, n]) => { for (let i = 0; i < n; i++) out.push({ ev, r: 'home', s: 'x' + i, src: 'direct', t: Date.now() - Math.random() * 30 * 864e5, p: ev === 'outbound' ? { deal: Math.random() > .5 } : ev === 'search' ? { q: ['food bank', 'ramadan grant', 'hall hire', 'warm space', 'gazebo', 'dbs', 'youth club', 'jummah times'][i % 8], zero: i % 3 === 0 } : {}, ex: 1 }); }); return out; };
V.analytics = () => { if (!isOwner) return `<div class="wrap">${back('home', 'Home')}<div class="empty">Owner only.</div></div>`; if (AN === null) { loadAnalytics(); return `<div class="wrap">${back('admin', 'Approval queue', 'Analytics')}<div class="empty">Loading…</div></div>`; }
  const ex = !AN.length, ev = (ex ? anSample() : AN).filter(e => e.t >= Date.now() - anDays * 864e5), views = ev.filter(e => e.ev === 'page_view'), sess = new Set(views.map(e => e.s));
  const cnt = (l, f) => Object.entries(l.reduce((o, e) => { const k = f(e); if (k) o[k] = (o[k] || 0) + 1; return o; }, {})).sort((a, b) => b[1] - a[1]);
  const byDay = {}; views.forEach(e => { const d = ISO(new Date(e.t)); byDay[d] = (byDay[d] || 0) + 1; }); const days = Object.entries(byDay).sort(), mx = Math.max(1, ...days.map(d => d[1]));
  const n = k => ev.filter(e => e.ev === k).length, pct = (a, b) => b ? Math.round(a / b * 100) + '%' : '–';
  const bars = (l, lab = x => x) => `<div class="bars">${l.slice(0, 8).map(([k, v]) => `<div class="br"><span>${esc(lab(k))}</span><span class="bt"><i style="width:${v / l[0][1] * 100}%"></i></span><b>${v}</b></div>`).join('') || '<p class="note">No data yet.</p>'}</div>`;
  const zero = cnt(ev.filter(e => e.ev === 'search' && e.p?.zero), e => e.p.q);
  return `<div class="wrap">${back('admin', 'Approval queue', 'Analytics')}<h1>Analytics</h1><p class="lede">First-party and cookie-free. Anonymous visits use a session ID held in memory only; no raw IP addresses are stored.</p>${ex ? '<p><span class="tag ex">Example</span> <span class="note">No real visits recorded yet, so this shows example data.</span></p>' : ''}
  <div class="row noprint" style="margin-bottom:14px">${[7, 30, 90].map(d => `<button class="chip${anDays === d ? ' on' : ''}" data-andays="${d}">${d} days</button>`).join('')}<button class="btn s sm" data-ancsv>${ic('dl')} CSV</button><button class="btn s sm" data-anjson>${ic('dl')} JSON for weekly reports</button></div>
  <div class="grid tight"><div class="stat"><b>${sess.size}</b><p>Visits (sessions)</p></div><div class="stat"><b>${views.length}</b><p>Page views</p></div><div class="stat"><b>${pct(n('signup_completed'), sess.size)}</b><p>Visit to account</p></div><div class="stat"><b>${n('promo_click')}</b><p>Promo clicks</p></div></div>
  <div class="dlbox" style="margin-top:14px"><h3>Page views over time</h3><svg viewBox="0 0 ${Math.max(days.length, 1) * 12} 80" style="width:100%;height:120px" preserveAspectRatio="none" role="img" aria-label="Page views per day">${days.map(([d, v], i) => `<rect x="${i * 12 + 1}" y="${78 - v / mx * 74}" width="10" height="${v / mx * 74}" rx="2" fill="var(--blue)"><title>${d}: ${v}</title></rect>`).join('')}</svg></div>
  <div class="two" style="margin-top:14px;align-items:start"><div class="dlbox"><h3>Top pages and features</h3>${bars(cnt(views, e => e.r), k => (META[k] || [0, k])[1])}</div><div class="dlbox"><h3>Traffic sources</h3>${bars(cnt(views.filter((e, i, l) => l.findIndex(z => z.s === e.s) === i), e => e.src))}</div>
  <div class="dlbox"><h3>Funnels</h3><table class="t"><tr><td>Visit → sign-up started → completed</td><td>${sess.size} → ${n('signup_started')} → ${n('signup_completed')} (${pct(n('signup_completed'), n('signup_started'))})</td></tr><tr><td>Questionnaire started → submitted</td><td>${n('questionnaire_started')} → ${n('questionnaire_submitted')} (${pct(n('questionnaire_submitted'), n('questionnaire_started'))})</td></tr><tr><td>Deal views → link-outs</td><td>${views.filter(e => e.r === 'discounts').length} → ${ev.filter(e => e.ev === 'outbound' && e.p?.deal).length}</td></tr><tr><td>Design & Print clicks</td><td>${n('design_print_click')}</td></tr><tr><td>HD logo downloads</td><td>${n('logo_hd_download')}</td></tr><tr><td>Forms created / responses</td><td>${n('form_created')} / ${n('form_response')}</td></tr></table></div>
  <div class="dlbox"><h3>Searches with no results</h3><p class="note">Content gaps to fill.</p>${bars(zero)}</div>
  <div class="dlbox"><h3>Devices</h3>${bars(cnt(views, e => e.dev))}</div><div class="dlbox"><h3>Signed-in organisations</h3>${bars(cnt(ev.filter(e => e.org), e => e.org), k => (H.DIR.find(o => o.id === k) || {}).n || k)}</div></div>
  <p class="note" style="margin-top:14px">For the live site, see server/README.md: a PHP and SQLite endpoint that counts unique visitors with a daily-rotating salted hash, never storing raw IPs.</p></div>`; };
document.addEventListener('click', e => { const b = e.target.closest('[data-andays],[data-ancsv],[data-anjson]'); if (!b) return; if (b.dataset.andays) { anDays = +b.dataset.andays; render(); } const l = AN && AN.length ? AN : anSample(); if ('ancsv' in b.dataset) saveBlob(new Blob(['time,event,route,source,device,org,detail\n' + l.map(e => [new Date(e.t).toISOString(), e.ev, e.r, e.src, e.dev, e.org || '', JSON.stringify(e.p || {}).replace(/"/g, "'")].map(v => '"' + v + '"').join(',')).join('\n')], { type: 'text/csv' }), 'hub-analytics.csv'); if ('anjson' in b.dataset) saveBlob(new Blob([JSON.stringify({ generated: new Date().toISOString(), example: !(AN && AN.length), events: l }, null, 1)], { type: 'application/json' }), 'hub-analytics.json'); });

/* ---------- personalisation (signed-in organisations only, can be switched off) ---------- */
const persOn = () => !!profile && profile.personal !== false;
const interests = () => { if (!profile) return null; const a = store.get('activity', []), used = {}; store.get('mine', []).forEach(s => used[s.kind] = (used[s.kind] || 0) + 1); const txt = a.map(x => x.t.toLowerCase()).join(' | ');
  return { type: profile.type || 'community', area: (myOrg()?.pc || '').split(' ')[0], causes: (profile.alerts?.causes || []), forms: forms().length, appeals: used.appeal || 0, freeposts: used['free-post'] || 0, logos: (txt.match(/downloaded a logo/g) || []).length, saved: (typeof saved === 'function' ? saved().length : 0), jummah: !!store.get('jtimes', {})[profile.orgId], requests: Object.keys(used).length, link: !!profile.link }; };
const SEGRULES_SEED = [
  { id: 's1', name: 'Charities running appeals', test: 'appeals>0 && type=charity', promo: 'p1', why: 'You’ve used appeal pages and you’re a charity.' },
  { id: 's2', name: 'Schools using forms', test: 'forms>0 && type=school', promo: 'p3', why: 'You’re a school and you’ve made a form.' },
  { id: 's3', name: 'Mosques sharing Jummah times', test: 'jummah && type=faith', promo: 'p5', why: 'You’re a mosque that shares Jummah times.' },
  { id: 's4', name: 'Regular free post users', test: 'freeposts>=3', promo: 'p3', why: 'You’ve requested 3 or more free posts.' },
  { id: 's5', name: 'Logo downloaders', test: 'logos>0', promo: 'p8', why: 'You’ve downloaded logos.' },
];
const segRules = () => (approved.find(a => a.id === 'segrules') || {}).items || store.get('segrules', null) || SEGRULES_SEED;
const segMatch = (rule, I) => rule.test.split('&&').every(c => { c = c.trim(); let m; if ((m = c.match(/^(\w+)\s*(>=|>|=)\s*(\w+)$/))) { const v = I[m[1]], w = isNaN(+m[3]) ? m[3] : +m[3]; return m[2] === '=' ? String(v) === String(w) : m[2] === '>' ? v > w : v >= w; } return !!I[c]; });
const mySegments = () => { const I = interests(); return I ? segRules().filter(r => segMatch(r, I)) : []; };
const RECS = [['linkpage', I => !I.link, 'You haven’t set up your one link yet.'], ['forms', I => !I.forms, 'Collect feedback for funders with ready-made templates.'], ['prayer', I => I.type === 'faith' && !I.jummah, 'Keep your Jummah times up to date for your community.'], ['policies', I => true, 'Check which policies your organisation needs.'], ['funding', I => ['charity', 'community', 'youth'].includes(I.type), 'Grants that match organisations like yours.'], ['training', I => true, 'Free courses for your staff and volunteers.'], ['brand', I => I.logos > 0, 'You’ve downloaded logos: keep your brand kit in one place.'], ['calendar', I => I.type !== 'school', 'Share your dates and avoid clashes.']];
const recommended = () => { if (!persOn()) return ''; const I = interests(); const l = RECS.filter(r => META[r[0]] && r[1](I)).slice(0, 4); return l.length ? `<h2 style="margin-top:24px">Recommended for you</h2><div class="board">${l.map(r => `<a class="tile" href="#${r[0]}">${tic(r[0])}<div><b>${META[r[0]][1]}</b><span>${r[2]}</span></div></a>`).join('')}</div><p class="note"><button class="linkbtn" data-whyrec>Why am I seeing this?</button></p>` : ''; };
const promosForMe = () => { if (!profile) return []; const base = promosFor(profile.type); if (!persOn()) return base; const seg = mySegments().map(s => s.promo); return [...promosAll().filter(p => seg.includes(p.id)), ...base].filter((p, i, l) => l.findIndex(z => z.id === p.id) === i); };
document.addEventListener('click', e => { const b = e.target.closest('[data-whyrec],[data-persoff]'); if (!b) return; if ('persoff' in b.dataset) { saveProfile({ ...profile, personal: profile.personal === false }); toast(profile.personal === false ? 'Personalised recommendations off' : 'Personalised recommendations on'); return render(); } const segs = mySegments(); modal(`<div class="mhead"><h3>Why am I seeing this?</h3><button class="ib" data-close>${ic('x')}</button></div><p>We suggest tools and offers based on your organisation’s type and how your account uses the hub: things like the tools you’ve opened, forms you’ve made and requests you’ve sent. We never use sensitive information about individuals.</p>${segs.length ? `<ul class="ticks" style="margin:10px 0">${segs.map(s => `<li>${esc(s.why)}</li>`).join('')}</ul>` : ''}<p>You can switch this off at any time. You’ll still see general suggestions for ${esc(C.TYPES[profile.type] || 'organisations')}.</p><div class="row"><button class="btn s" data-persoff>${persOn() ? 'Turn off personalised recommendations' : 'Turn them back on'}</button><a class="btn o" href="#privacy" data-close>Privacy notice</a></div>`); });
V.segments = () => { if (!isOwner) return `<div class="wrap"><div class="empty">Owner only.</div></div>`; const rules = segRules();
  return `<div class="wrap">${back('admin', 'Approval queue', 'Segments')}<h1>Segments</h1><p class="lede">Rules that target promotions at organisations, based on organisation type and how they use the hub. No sensitive data about individuals is used.</p><p class="note">Counts come from organisation profiles once the live backend aggregates them; in this preview they use this device only.</p>
  <div class="grid">${rules.map(r => `<div class="card"><h3>${esc(r.name)}</h3><p><code>${esc(r.test)}</code></p><div class="meta"><span>Promo: ${esc((promosAll().find(p => p.id === r.promo) || {}).t || r.promo)}</span><span>${profile && segMatch(r, interests()) ? '1 (this device)' : '0'} matching</span></div><p class="note">Shown as: “${esc(r.why)}”</p><button class="btn o sm" data-segdel="${r.id}">Remove</button></div>`).join('')}</div>
  <form class="form dlbox" id="segForm" style="margin-top:16px"><h2>Add a rule</h2><label class="f">Name<input class="in" name="name" required></label><label class="f">Test<input class="in" name="test" required placeholder="appeals>0 && type=charity"><small>Fields: type, area, forms, appeals, freeposts, logos, saved, jummah, requests, link. Join with &&.</small></label><label class="f">Promotion<select class="in" name="promo">${promosAll().map(p => `<option value="${p.id}">${esc(p.t)}</option>`).join('')}</select></label><label class="f">“Why am I seeing this?” text<input class="in" name="why" required></label><button class="btn p">Save rule</button></form></div>`; };
const saveSeg = async l => { store.set('segrules', l); if (db && isOwner) { try { await db.collection('approved').doc('segrules').set({ kind: 'segrules', status: 'meta', items: l, at: Date.now() }); } catch (e) { } } render(); };
document.addEventListener('submit', e => { if (e.target.id !== 'segForm') return; e.preventDefault(); e.stopImmediatePropagation(); const r = Object.fromEntries(new FormData(e.target)); r.id = 's' + Date.now(); saveSeg([...segRules(), r]); }, true);
